effect.frag.content:
int sourceIndex = 0;
uniform float u_amount;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return imageAt(sourceIndex, uv);
}
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = vec4(0.0);
  float distance = 0.28 - sin(3.14159265359 * u_progress) * u_amount * 0.2;
  for (int i = 0; i < 4; i++) {
    sourceIndex = i;
    vec2 sign = vec2(float(i % 2), float(i / 2)) * 2.0 - 1.0;
    color = over(sourceAt((v_uv - 0.5 - sign * distance) / 0.42 + 0.5), color);
  }
  fragColor = color;
}
